// 용어 설명 자료(TERM_GLOSSARY_KO, 한국어 기준 모양) — "?" 용어 설명(term_hint.jsx TermHint)이 읽는 한 곳. React 없음(데이터만).
// 항목: key → { term: 보일 이름, def: 한두 문장 정의, unit?: 대표 단위, ref?: 근거 }. 계산기 정의의 term: "<key>" 가 여기를 가리킨다.
// 새 용어는 여기에 한 줄 더하고 쓰는 곳에 term 을 붙인다. 쓰이지 않는 항목·없는 key 는 시험(test_calculators.cjs)이 잡는다.
// 영어는 term_glossary_en.jsx(TERM_GLOSSARY_EN, 같은 key) — 거기서 langPick 으로 화면이 읽는 TERM_GLOSSARY·TERM_HINT_LABELS 를 만든다.

const TERM_HINT_LABELS_KO = {
  button: (term) => `${term} 용어 설명`,
  unit: "단위",
  ref: "근거",
  more: "용어사전에서 보기",
};

