  afr: { term: "공연비 (AFR)", def: "연료 질량에 대한 공기 질량의 비입니다. 이론 공연비보다 크면 공기가 남는 희박 연소입니다.", unit: "kg/kg" },
  excess_air: { term: "과잉 공기율", def: "이론 공기량보다 더 넣은 공기의 비율입니다. 20 % 면 이론량의 1.2 배를 넣은 것입니다.", unit: "%" },
  cst: { term: "양론 농도 Cst", def: "연료와 공기가 과부족 없이 완전 연소하는 비율일 때 공기 혼합물 속 연료의 부피 농도입니다.", unit: "vol%", ref: "Crowl & Louvar 6장" },
